for name,x in [('rev',pd.concat({s:-P[s].pct_change(5) for s in U},axis=1)),('mom',pd.concat({s:P[s].pct_change(20)/P[s].pct_change().rolling(20).std() for s in U},axis=1))]: print('corr',name,round(f.stack().corr(x.stack()),4))
"}

